using System;
using System.Linq;
using System.Reflection;
using UnityEditor;
using UnityEngine;
using UnityEngine.UI;
namespace CatCafePreview.Editor
{
    public static class PythonEventGroupsVerification
    {
        static void Check(bool value,string message){if(!value)throw new Exception(message);}
        public static void BuildAndVerify()
        {
            PythonEventListSetup.Build();var p=UnityEngine.Object.FindObjectOfType<ContentPreview>();p.Initialize();var client=p.GetComponent<PythonStateClient>();var flags=BindingFlags.Instance|BindingFlags.NonPublic;typeof(PythonStateClient).GetField("preview",flags).SetValue(client,p);
            var state=PythonServiceSetup.Sample();state.instance_id="event-groups";state.can_set_shifts=true;state.required_action="";
            state.visiting_cat=new PythonVisitingCat{cat_id="visit-1",name="ココ",status="visiting",progress=1,required=3,can_interact=true};
            state.intake_request=new PythonIntakeState{cat_id="new-cat",name="ハル",status="waiting",can_decline=true};
            state.store_event=new PythonStoreEvent{kind="support",title="店舗への依頼",choices=new[]{new PythonEventChoice{choice="decline",label="見送る",can_select=true}}};
            state.growth_choices=new[]{new PythonGrowthChoice{cat_id="cat-mike",name="ミケ",kind="resolve_growth_type_mastery",title="成長",choices=new[]{new PythonEventChoice{choice="voice",label="声をかける",can_select=true}}},new PythonGrowthChoice{cat_id="cat-tama",name="タマ",kind="resolve_growth_type_mastery",title="成長",choices=new[]{new PythonEventChoice{choice="voice",label="声をかける",can_select=true}}}};
            state.autoplay=new PythonAutoPlay{objectives=new PythonAutoPlayOption[0],modes=new PythonAutoPlayOption[0]};
            state.patron_dispatch=new PythonPatronDispatch{options=new[]{new PythonDispatchOption{cat_id="cat-mike",choice="patron-test",label="有力者派遣",can_select=false}},events=new PythonDispatchEvent[0]};
            Action apply=()=>typeof(PythonStateClient).GetMethod("Accept",flags).Invoke(client,new object[]{state});apply();var list=p.GetComponent<PythonEventListPanel>();list.Open();
            Check(list.PendingCount==4 && list.SelectedGroup==0 && list.open.GetComponentInChildren<Text>().text.Contains("4件"),"Pending badge or priority");
            int total=0;for(int g=0;g<4;g++){list.tabs[g].onClick.Invoke();for(int i=0;i<list.entries.Length;i++){bool visible=list.entries[i].gameObject.activeSelf;Check(visible==(i<14 && list.GroupFor(i)==g),"Incorrect grouping "+i);if(visible)total++;if(i<14)Check(list.detailPanels[i]!=null && list.detailClose[i]!=null,"Missing return route "+i);}Capture(p,"EventGroup-"+g);}
            Check(total==14,"Duplicate or missing routes");list.tabs[1].onClick.Invoke();list.entries[0].onClick.Invoke();var visiting=p.GetComponent<PythonVisitingCatPanel>();Check(visiting.close.GetComponentInChildren<Text>().text=="イベント一覧へ戻る","Visiting caption");visiting.close.onClick.Invoke();Check(list.panel.activeSelf && list.SelectedGroup==1 && !visiting.panel.activeSelf,"Visiting return lost group");
            list.Open();list.entries[1].onClick.Invoke();Check(!list.panel.activeSelf && list.detailClose[1].gameObject.activeSelf,"Mandatory return unavailable");Capture(p,"EventIntakeReturn");list.detailClose[1].onClick.Invoke();Check(list.panel.activeSelf && list.SelectedGroup==0 && state.intake_request.status=="waiting" && !list.detailClose[1].gameObject.activeSelf,"Back answered mandatory event");
            list.entries[2].onClick.Invoke();list.detailClose[2].onClick.Invoke();Check(list.panel.activeSelf,"Store return");list.entries[3].onClick.Invoke();list.detailClose[3].onClick.Invoke();Check(list.panel.activeSelf,"Growth return");
            list.entries[1].onClick.Invoke();state.intake_request.status="declined";apply();Check(list.panel.activeSelf && list.PendingCount==3 && list.GroupFor(1)==3,"Resolved event did not move to records or return");
            list.tabs[1].onClick.Invoke();list.entries[0].onClick.Invoke();var menu=p.GetComponent<PythonMenuPanel>();menu.Open();visiting.close.onClick.Invoke();Check(menu.panel.activeSelf && !list.panel.activeSelf,"Old return leaked into menu");menu.SelectGroup(1);menu.entries[11].onClick.Invoke();var dispatch=p.GetComponent<PythonDispatchPanel>();Check(dispatch.panel.activeSelf && dispatch.close.GetComponentInChildren<Text>().text=="メニューへ戻る","Dispatch menu caption");dispatch.close.onClick.Invoke();Check(menu.panel.activeSelf && !list.panel.activeSelf && menu.SelectedGroup==1,"Menu dispatch returned to event list");menu.Close();menu.Open();menu.entries[0].onClick.Invoke();list.Open();p.RefreshPythonControls();Check(list.panel.transform.GetSiblingIndex()==list.panel.transform.parent.childCount-1 && !p.GetComponent<PythonAutoPlayPanel>().panel.activeSelf,"Menu detail obscured event list");list.Close();visiting.Open();visiting.close.onClick.Invoke();Check(!list.panel.activeSelf,"Direct detail returned to list");
            list.Open();typeof(PythonStateClient).GetField("pending",flags).SetValue(client,new PythonShiftCommand{kind="test"});p.RefreshPythonControls();Check(list.entries.Take(14).All(b=>!b.interactable),"Busy event enabled");typeof(PythonStateClient).GetField("pending",flags).SetValue(client,null);typeof(PythonStateClient).GetField("online",flags).SetValue(client,false);p.PythonConnectionError("test");Check(list.entries.Take(14).All(b=>!b.interactable) && list.notice.text.Contains("未接続"),"Offline event enabled");
            apply();list.tabs[1].onClick.Invoke();list.entries[0].onClick.Invoke();state.instance_id="loaded";state.intake_request=null;state.store_event=null;state.growth_choices=null;apply();Check(!list.panel.activeSelf && list.PendingCount==0 && list.SelectedGroup==1,"Loaded game retained old navigation");visiting.close.onClick.Invoke();Check(!list.panel.activeSelf,"Loaded game retained return");
            var counts=PythonServiceSetup.Sample();counts.instance_id="count-only";counts.intake_request=new PythonIntakeState{status="waiting"};counts.store_event=new PythonStoreEvent();counts.growth_choices=new PythonGrowthChoice[2];counts.missing_cats=new[]{new PythonMissingCat{status="waiting"},new PythonMissingCat{status="missing"}};counts.adoption=new PythonAdoption{events=new[]{new PythonAdoptionEvent{status="waiting"}}};counts.patron_dispatch=new PythonPatronDispatch{events=new[]{new PythonDispatchEvent{status="waiting"},new PythonDispatchEvent{status="travelling"}}};counts.regular_introduction=new PythonRegularIntroduction{status="waiting"};counts.reservation=new PythonReservation{status="waiting"};counts.customer_trust=new PythonCustomerTrust{events=new[]{new PythonTrustEvent{status="waiting"}}};counts.general_dispatch=new PythonPatronDispatch{events=new[]{new PythonDispatchEvent{status="waiting"}}};counts.dispatch_choices=new[]{new PythonDispatchEncounter{status="waiting"}};counts.dispatch_troubles=new[]{new PythonDispatchTrouble{status="waiting"}};counts.dispatch_introductions=new[]{new PythonDispatchIntroduction{status="waiting"}};list.Apply(counts);Check(list.PendingCount==14,"Waiting count omitted an event or counted travellers");list.Open();list.SelectGroup(0);Check(list.content.rect.height>list.scroll.viewport.rect.height,"Many pending events cannot scroll");Capture(p,"EventManyPending");apply();
            Check(typeof(PythonStateClient).GetField("pending",flags).GetValue(client)==null,"Navigation sent game command");Debug.Log("CAT_CAFE_EVENT_GROUPS_OK: 14 routes / 4 tabs / pending counts / mandatory back / resolved records / return context / busy / offline / load / scrolling");
        }
        public static void VerifyRegression(){BuildAndVerify();PythonEventListSetup.BuildAndVerify();PythonMenuGroupsVerification.BuildAndVerify();PythonBusinessHeaderVerification.BuildAndVerify();Debug.Log("CAT_CAFE_EVENT_GROUPS_REGRESSION_OK");}
        static void Capture(ContentPreview p,string name){Canvas.ForceUpdateCanvases();typeof(ContentPreviewSetup).GetMethod("CaptureCanvas",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{p,"Logs/"+name+".png"});}
    }
}
